$ErrorActionPreference='Stop'
$auditRoot='C:\Users\gb\.codex\tmp\pvground_extremal_span_evidence_20261009\runner_v1\source_review'
$manifest=@(Get-Content -LiteralPath "$auditRoot\INPUT_MANIFEST.json" -Raw -Encoding utf8 | ConvertFrom-Json)
foreach($entry in $manifest) { if((Get-FileHash -LiteralPath $entry.path -Algorithm SHA256).Hash.ToLower() -ne $entry.sha256) { throw "Changed original: $($entry.path)" }; if((Get-FileHash -LiteralPath (Join-Path $auditRoot $entry.snapshot) -Algorithm SHA256).Hash.ToLower() -ne $entry.sha256) { throw "Changed snapshot: $($entry.snapshot)" } }
$report=Get-Content -LiteralPath "$auditRoot\SOURCE_REVIEW_R1.json" -Raw -Encoding utf8 | ConvertFrom-Json
if($report.verdict_scope -ne 'STATIC_ONLY' -or $report.launch_approved -or $report.actual_neural_forwards -ne 0) {throw 'Review scope mismatch'}
$rawHash=(Get-FileHash -LiteralPath "$auditRoot\RAW_RESPONSE_R1.md" -Algorithm SHA256).Hash.ToLower()
if($rawHash -ne (Get-FileHash -LiteralPath "$auditRoot\SOURCE_REVIEW_R1.md" -Algorithm SHA256).Hash.ToLower()) {throw 'Raw report mismatch'}
$attempts=@(); foreach($index in 1..4) { $receipt=Get-Content -LiteralPath (Join-Path $auditRoot "NATIVE_VERIFICATION_ATTEMPT_$index.json") -Raw -Encoding utf8 | ConvertFrom-Json; $attempts += $receipt.result.exit_code }
if(($attempts -join ',') -ne '1,1,1,0') {throw 'Invocation exits mismatch'}
$artifactHashes=@(); foreach($file in Get-ChildItem -LiteralPath $auditRoot -File) { $artifactHashes += [pscustomobject]@{name=$file.Name;bytes=$file.Length;sha256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLower()} }
$verification=[pscustomobject]@{time_utc=[DateTime]::UtcNow.ToString('o');original_inputs_and_snapshots_still_exact=$manifest.Count;raw_and_formatted_report_exact=$true;scope='STATIC_ONLY';launch_approved=$false;invocation_exit_codes=$attempts;artifact_hashes=$artifactHashes}
$verification | ConvertTo-Json -Depth 7 | Set-Content -LiteralPath "$auditRoot\FINAL_VERIFICATION_R1.json" -Encoding utf8
$verification | ConvertTo-Json -Depth 7

